// Generated by `bun run wallpapers`: pixel and file sizes of each original.
import sizes from "./wallpaper-meta.json";

export type Device = "iphone" | "mac";

export interface WallpaperEntry {
	/** Folder name under public/wallpapers/. */
	slug: string;
	name: string;
	/** Original file extension per device, e.g. { iphone: "png", mac: "png" }. */
	variants: Partial<Record<Device, string>>;
}

export interface Variant {
	/** WebP preview shown on the card. */
	preview: string;
	/** Full-resolution original. */
	original: string;
	/** Suggested filename for the download. */
	filename: string;
	/** Shown under the title, e.g. "1672 × 941 · PNG · 1.5 MB". */
	specs: string;
}

/** One card on the wallpapers page: a wallpaper with every device it supports. */
export interface Wallpaper {
	slug: string;
	name: string;
	variants: Partial<Record<Device, Variant>>;
}

/**
 * To add a wallpaper:
 *  1. Drop the originals in public/wallpapers/<slug>/ as iphone.png and/or mac.png
 *  2. Run `bun run wallpapers` to generate the WebP previews
 *  3. Add an entry here (newest first)
 * Keep names short (about 3 words): they sit on one line next to the Download button.
 */
export const wallpaperEntries: WallpaperEntry[] = [
	{
		slug: "neon-ribbon-wave",
		name: "Neon Ribbon Wave",
		variants: { iphone: "png", mac: "png" },
	},
	{
		slug: "amber-diagonal-glow",
		name: "Amber Diagonal Glow",
		variants: { iphone: "png", mac: "png" },
	},
];

function formatSpecs(key: string, ext: string) {
	const meta = (sizes as Record<string, { width: number; height: number; bytes: number } | undefined>)[key];
	if (!meta) return ext.toUpperCase();
	return `${meta.width} × ${meta.height} · ${ext.toUpperCase()} · ${(meta.bytes / 1_000_000).toFixed(1)} MB`;
}

export function getWallpapers(): Wallpaper[] {
	return wallpaperEntries.map(({ slug, name, variants }) => ({
		slug,
		name,
		variants: Object.fromEntries(
			(Object.entries(variants) as [Device, string][]).map(([device, ext]) => [
				device,
				{
					preview: `/wallpapers/${slug}/${device}.webp`,
					original: `/wallpapers/${slug}/${device}.${ext}`,
					filename: `${slug}-${device}.${ext}`,
					specs: formatSpecs(`${slug}/${device}`, ext),
				},
			]),
		),
	}));
}
